// DoorLockAdapter contract (README section 3.4 v0.2). Owner: INT. R2 'manual'; automatic once the brand is known.
import type { HealthStatus, IntegrationContext, IsoInstant } from './common.js';

export interface DoorLockCapabilities {
  remote: boolean;
  customCode: boolean;
  codeLength: { min: number; max: number };
  card: boolean;
  fingerprint: boolean;
  logs: boolean;
  /** Display only (lock safety level, T11). */
  lockoutAfterFailedAttempts?: number;
}

export interface CreateDoorCodeRequest {
  lockRef: string;
  /** 6–10 digits generated by the core with a CSPRNG (SR-LOCK-01). The adapter never returns it. */
  code: string;
  kind: 'guest' | 'staff';
  validFrom: IsoInstant;
  validTo: IsoInstant;
  /** ONLY a random internal reference – no name/phone/birthday (SEC-08). */
  label: string;
}

export interface CreateDoorCodeResult {
  credentialId: string;
  /** manual: false → core creates the task "Install code in the lock app". */
  installed: boolean;
}

export interface AddKeyCardRequest {
  lockRef: string;
  keyCardUid: string;
  validFrom: IsoInstant;
  validTo: IsoInstant;
  label: string;
}

export interface DoorAccessLogEntry {
  at: IsoInstant;
  method: 'code' | 'card' | 'fingerprint' | 'app' | 'key';
  credentialId?: string;
}

export interface DoorLockAdapter {
  capabilities(ctx: IntegrationContext, lockRef: string): Promise<DoorLockCapabilities>;
  createCode(ctx: IntegrationContext, req: CreateDoorCodeRequest): Promise<CreateDoorCodeResult>;
  updateValidity(
    ctx: IntegrationContext,
    credentialId: string,
    validFrom: IsoInstant,
    validTo: IsoInstant,
  ): Promise<void>;
  revoke(ctx: IntegrationContext, credentialId: string): Promise<void>;
  addCard?(ctx: IntegrationContext, req: AddKeyCardRequest): Promise<{ credentialId: string }>;
  accessLog?(
    ctx: IntegrationContext,
    lockRef: string,
    since: IsoInstant,
  ): Promise<DoorAccessLogEntry[]>;
  healthCheck(ctx: IntegrationContext): Promise<HealthStatus>;
}
